The root of the problem is that a classmate asked about a lucky number problem: Codeforces 280B. Codeforces 281D is the same problem.
Find all unique pairs of maximum and second maximum elements over all sub-arrays in O(NlogN)
A lucky number is defined as the XOR value of the maximum and second maximum of a subarray. The task is to find the largest lucky number among all lucky numbers.
The brute force solution enumerates all subarrays, with time complexity O(N ^ 2).Is there a better method?That is the problem to discuss today.
General Solution: Fast Algorithm for Finding Maximum and Second-Maximum PairsThere is actually a fast algorithm for finding the maximum and second maximum in subarrays:Find all unique pairs of maximum and second maximum elements over all sub-arrays in O(NlogN)
It is based on this observation: for each number in the array, if it wants to become the second maximum, it can only pair with the first number greater than it in front of it, or the first number greater than it after it.We can maintain a monotonically decreasing stack. When adding a new number, to maintain monotonicity we pop all numbers smaller than it. At this time, the new number is the first number after the popped numbers that is greater than them; the largest number on the stack top is the first number before the new number that is greater than it.
Time complexity: O(N),space complexity: O(N).
#include &lt;iostream&gt;#include &lt;stack&gt;#include &lt;vector&gt;using namespace std;using ll = long long;int solve() &#123;    ll N;    cin &gt;&gt; N;    vector&lt;ll&gt; nums(N);    for (ll i = 0; i &lt; N; ++i) &#123;        cin &gt;&gt; nums[i];    &#125;    stack&lt;ll&gt; st;    st.push(nums[0]);    ll ans = 0;    for (ll i = 1; i &lt; N; ++i) &#123;        while (!st.empty() &amp;&amp; nums[i] &gt; st.top()) &#123;            ans = max(ans, nums[i] ^ st.top());            st.pop();        &#125;        if (!st.empty()) &#123;            ans = max(ans, nums[i] ^ st.top());        &#125;        st.push(nums[i]);    &#125;    return ans;&#125;int main() &#123;    ll ans = solve();    cout &lt;&lt; ans &lt;&lt; endl;    return 0;&#125;

The Solution I Thought of IndependentlyMy solution uses the property of XOR. If we replaced XOR with another operation, it would not be general.
First traverse once to find the highest bit.Then traverse again to find the numbers whose highest bit is 1. Let us call them the highest numbers.Starting from these highest numbers, expand to both sides until encountering another highest number. During this process, find the second maximum and update the maximum lucky number. It can be proven that each number is visited at most twice.Therefore, the total time complexity is O(N), and the space complexity is O(N).
#include &lt;iostream&gt;#include &lt;vector&gt;using namespace std;using ll = long long;int solve() &#123;    int N;    cin &gt;&gt; N;    vector&lt;ll&gt; nums(N);    for (ll i = 0; i &lt; N; ++i) &#123;        cin &gt;&gt; nums[i];    &#125;    const int MAX_BIT_BEGIN = 40;    vector&lt;vector&lt;ll&gt;&gt; flag(MAX_BIT_BEGIN + 1, vector&lt;ll&gt;(2, 0));    for (ll i : nums) &#123;        for (ll j = 0; j &lt;= MAX_BIT_BEGIN; ++j) &#123;            ++flag[j][((i &gt;&gt; j) &amp; 1)];        &#125;    &#125;    ll max_bit = MAX_BIT_BEGIN;    for (; max_bit &gt;= 0; --max_bit) &#123;        if (flag[max_bit][0] &gt; 0 &amp;&amp; flag[max_bit][1] &gt; 0) &#123;            break;        &#125;    &#125;    if (max_bit == 0) &#123;        return 1;    &#125; else if (max_bit &lt; 0) &#123;        return 0;    &#125; else &#123;        vector&lt;ll&gt; max_bit_is_1_indexs;        for (ll i = 0; i &lt; N; ++i) &#123;            if (((nums[i] &gt;&gt; max_bit) &amp; 1) == 1) &#123;                max_bit_is_1_indexs.push_back(i);            &#125;        &#125;        ll ans = 0;        for (ll index : max_bit_is_1_indexs) &#123;            ll second_max = 0;            for (ll i = index - 1; i &gt;= 0 &amp;&amp; ((nums[i] &gt;&gt; max_bit) &amp; 1) == 0;                 --i) &#123;                second_max = max(second_max, nums[i]);                ans = max(ans, nums[index] ^ second_max);            &#125;            second_max = 0;            for (ll i = index + 1; i &lt; N &amp;&amp; ((nums[i] &gt;&gt; max_bit) &amp; 1) == 0;                 ++i) &#123;                second_max = max(second_max, nums[i]);                ans = max(ans, nums[index] ^ second_max);            &#125;        &#125;        return ans;    &#125;&#125;int main() &#123;    ll ans = solve();    cout &lt;&lt; ans &lt;&lt; endl;    return 0;&#125;

A post-contest write-up.Problem link
Building PalindromesGiven a string of length N and Q queries. Each query is a range, from which we can get a substring. Determine whether the substring can be rearranged into a palindrome. Since arbitrary rearrangement is allowed, the order of characters in the substring does not matter; what matters is the frequency of each character. If the number of characters with odd frequency is 0 or 1, the substring can be rearranged into a palindrome.Because N and Q are large, 10^5, a quadratic algorithm will time out. Here we borrow the prefix sum idea to quickly compute character frequencies in a substring.The time complexity is linear.
#include &lt;vector&gt;#include &lt;iostream&gt;#include &lt;unordered_map&gt;#include &lt;algorithm&gt;using namespace std;int main(int argc, char const *argv[])&#123;    int T;    cin &gt;&gt; T;    for (int i = 1; i &lt;= T; ++i) &#123;        int N, Q;        cin &gt;&gt; N &gt;&gt; Q;        string s;        cin &gt;&gt; s;        vector&lt;vector&lt;int&gt;&gt; prefix(N+1);        prefix[0] = vector&lt;int&gt;(26, 0);        for (int j = 1; j &lt;= N; ++j) &#123;            prefix[j] = prefix[j-1];            ++prefix[j][s[j-1] - &#x27;A&#x27;];        &#125;        int ans = 0;        for (int j = 0; j &lt; Q; ++j) &#123;            int L, R;            cin &gt;&gt; L &gt;&gt; R;            const auto&amp; l = prefix[L-1], r = prefix[R];            int odd = 0;            for (int k = 0; k &lt; 26; ++k) &#123;                if ((r[k] - l[k]) % 2 == 1)                    ++odd;            &#125;            if (odd &lt;= 1)                ++ans;        &#125;        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; i &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;    &#125;    return 0;&#125;

Energy StonesThe idea of this problem is greedy + dynamic programming (a kind of 0-1 knapsack). For more knapsack problems, see Pack PDF.The hard part is that the traversal order for the knapsack needs to be sorted with a greedy idea.
For the small test set where S is the same, traverse stones with larger L first. This minimizes the lost energy.For the large test set where S differs, the order of two stones i and j is determined by S_i * L_j. If S_i * L_j &lt; S_j * L_i, eating i first loses less energy.
The correctness of the greedy approach is also easy to prove. If we have a sequence for eating stones, it must be in the order that loses less energy. Otherwise, swapping the order can obtain more energy.
Time complexity: O(N * N * S_i).Space complexity: O(N * N * S_i), which can be further optimized to O(N * S_i)
#include &lt;algorithm&gt;#include &lt;iostream&gt;#include &lt;tuple&gt;#include &lt;vector&gt;using namespace std;struct Stone &#123;  int s, e, l;  bool operator&lt;(const Stone &amp;p) const &#123; return s * p.l &lt; l * p.s; &#125;&#125;;int main(int argc, char const *argv[]) &#123;  int T;  cin &gt;&gt; T;  for (int iCase = 1; iCase &lt;= T; ++iCase) &#123;    int N;    cin &gt;&gt; N;    vector&lt;Stone&gt; data(N + 1);    int S_sum = 0;    for (int i = 1; i &lt;= N; ++i) &#123;      cin &gt;&gt; data[i].s &gt;&gt; data[i].e &gt;&gt; data[i].l;      S_sum += data[i].s;    &#125;    sort(data.begin() + 1, data.end());    vector&lt;vector&lt;int&gt;&gt; dp(N + 1, vector&lt;int&gt;(S_sum + 1));    for (int i = 1; i &lt;= N; ++i) &#123;      for (int time = 0; time &lt;= S_sum; ++time) &#123;        if (time &lt; data[i].s) &#123;          dp[i][time] = dp[i - 1][time];        &#125; else &#123;          dp[i][time] =              max(dp[i - 1][time],                  dp[i - 1][time - data[i].s] +                      max(0, data[i].e - data[i].l * (time - data[i].s)));        &#125;      &#125;    &#125;    int ans = 0;    for (int time = 0; time &lt;= S_sum; ++time) &#123;      ans = max(ans, dp[N][time]);    &#125;    cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;  &#125;  return 0;&#125;

Diverse SubarrayLike the first problem, this problem also needs prefix sums, but this transformation is not very obvious.First convert the types sequence into an increase/decrease event sequence. Then it becomes clear that the prefix sum of the event sequence is the final number of gifts we need to optimize.Then, to quickly obtain the maximum prefix sum, we can use a [Segment Tree](// https://www.geeksforgeeks.org/maximum-prefix-sum-given-range/). It supports querying the maximum prefix sum in a range in O(log N) and updating the segment tree in O(log N).
Overall time complexity: O(N log N)

Initialize the segment tree in O(N log N)
For N starting points, update and query the segment tree in O(log N)

#include &lt;algorithm&gt;#include &lt;iostream&gt;#include &lt;limits&gt;#include &lt;unordered_map&gt;#include &lt;vector&gt;using namespace std;struct SegmentTree &#123;  struct Node &#123;    int sum = numeric_limits&lt;int&gt;::min();    int prefix = numeric_limits&lt;int&gt;::min();    bool isValid() const &#123;      return sum != numeric_limits&lt;int&gt;::min() &amp;&amp;             prefix != numeric_limits&lt;int&gt;::min();    &#125;    Node &amp;operator=(const Node &amp;rhs) &#123;      this-&gt;sum = rhs.sum;      this-&gt;prefix = rhs.prefix;      return *this;    &#125;  &#125;;  const int MAX_N = 1 &lt;&lt; 17;  // 存储线段树的全局数组  vector&lt;Node&gt; dat;  int n;  // 初始化  SegmentTree(int n_, int a[]) &#123;    // 为简单起见，把元素个数扩大到2的幂    n = 1;    while (n &lt; n_)      n *= 2;    // 把所有的值都设为INT_MAX    dat.resize(2 * n);    for (int i = 0; i &lt; n_; ++i) &#123;      update(i, a[i]);    &#125;  &#125;  void print() const &#123;    for (const auto &amp;d : dat) &#123;      cout &lt;&lt; &quot;&#123;&quot; &lt;&lt; d.sum &lt;&lt; &quot;, &quot; &lt;&lt; d.prefix &lt;&lt; &quot;&#125;, &quot;;    &#125;    cout &lt;&lt; endl;  &#125;  // 把第k个值(0-indexed)更新为a  void update(int k, int a) &#123;    // 叶子节点    k += n - 1;    dat[k].sum = a;    dat[k].prefix = a;    // 向上更新    while (k &gt; 0) &#123;      k = (k - 1) / 2;      if (!dat[2 * k + 2].isValid())        dat[k] = dat[2 * k + 1];      else &#123;        dat[k].sum = dat[2 * k + 1].sum + dat[2 * k + 2].sum;        dat[k].prefix = max(dat[2 * k + 1].prefix,                            dat[2 * k + 1].sum + dat[2 * k + 2].prefix);      &#125;    &#125;  &#125;  // 求[beg, end)的最小值  // 后面的参数是为了计算起来方便而转入的。  // k 是节点的编号, l, r表示这个节点对应的是[l, r)区间。  // 在外部调用时，用query(index, beg, end, 0, n)  Node query(int index, const int beg, const int end, int l, int r) const &#123;    // cout &lt;&lt; &quot;(&quot; &lt;&lt; index &lt;&lt; &quot;, &quot; &lt;&lt; l &lt;&lt; &quot;, &quot; &lt;&lt; r &lt;&lt; &quot;);&quot; &lt;&lt; endl;    Node ret;    // 如果[beg, end) 和 [l, r)不相交，则返回INT_MAX    if (r &lt;= beg || end &lt;= l)      return ret;    // 如果[beg, end)完全包含[l, r), 则返回当前节点的值    if (beg &lt;= l &amp;&amp; r &lt;= end)      return dat[index];    int mid = l + (r - l) / 2;    auto vl = query(index * 2 + 1, beg, end, l, mid);    auto vr = query(index * 2 + 2, beg, end, mid, r);    if (!vr.isValid()) &#123;      ret = vl;    &#125; else if (!vl.isValid()) &#123;      ret = vr;    &#125; else &#123;      ret.sum = vl.sum + vr.sum;      ret.prefix = max(vl.prefix, vl.sum + vr.prefix);    &#125;    return ret;  &#125;  Node queryMin(const int a, const int b) const &#123; return query(0, a, b, 0, n); &#125;&#125;;// https://www.geeksforgeeks.org/maximum-prefix-sum-given-range/int main(int argc, char const *argv[]) &#123;  int T;  cin &gt;&gt; T;  for (int iCase = 1; iCase &lt;= T; ++iCase) &#123;    int N, S;    cin &gt;&gt; N &gt;&gt; S;    vector&lt;int&gt; A(N), events(N);    unordered_map&lt;int, vector&lt;int&gt;&gt; types; // type, &lt;index&gt;    for (int i = 0; i &lt; N; ++i) &#123;      cin &gt;&gt; A[i];      types[A[i]].push_back(i);      if (types[A[i]].size() &lt;= S) &#123;        events[i] = 1;      &#125; else if (types[A[i]].size() == S + 1) &#123;        events[i] = -S;      &#125; else &#123;        events[i] = 0;      &#125;    &#125;    SegmentTree st(N, events.data());    int ans = numeric_limits&lt;int&gt;::min();    for (int i = 0; i &lt; N; ++i) &#123;      auto r = st.queryMin(i, N);      ans = max(ans, r.prefix);      auto &amp;v = types[A[i]];      auto it = lower_bound(v.begin(), v.end(), i);      if (it + S &lt; v.end()) &#123;        st.update(*(it + S), 1);        if (it + S + 1 &lt; v.end())          st.update(*(it + S + 1), -S);      &#125;    &#125;    cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;  &#125;  return 0;&#125;

