The main references were Kuang Shen’s livestream solution and the official Analysis.
Wiggle WalkThe easy idea is brute force. Simulate the entire command execution process and mark whether each cell has been visited before.Time complexity: O(N ^ 2).
Although this happened to AC in practice, it is risky. In theory, it would TLE on the large test set.
#include &lt;vector&gt;#include &lt;iostream&gt;#include &lt;string&gt;using namespace std;pair&lt;int, int&gt; solve(const string&amp; instructions, const int R, const int C, const int Sr, const int Sc) &#123;    int current_x = Sr, current_y = Sc;    vector&lt;vector&lt;bool&gt;&gt; visited(R + 1, vector&lt;bool&gt; (C + 1, false));    visited[current_x][current_y] = true;    for (char c : instructions) &#123;        int dx, dy;        switch (c)        &#123;        case &#x27;N&#x27;:            dx = -1;            dy = 0;            break;        case &#x27;E&#x27;:            dx = 0;            dy = 1;            break;        case &#x27;W&#x27;:            dx = 0;            dy = -1;            break;        case &#x27;S&#x27;:            dx = 1;            dy = 0;            break;        default:            cerr &lt;&lt; &quot;Bad instruction: &quot; &lt;&lt; c &lt;&lt; endl;            break;        &#125;        do &#123;            current_x += dx;            current_y += dy;        &#125; while (visited[current_x][current_y] == true);        visited[current_x][current_y] = true;    &#125;    return &#123;current_x, current_y&#125;;&#125;int main() &#123;    int T;    cin &gt;&gt; T;    for (int i = 0; i &lt; T; ++i) &#123;        int N, R, C, Sr, Sc;        cin &gt;&gt; N &gt;&gt; R &gt;&gt; C &gt;&gt; Sr &gt;&gt; Sc;        string instructions;        cin &gt;&gt; instructions;        auto ans = solve(instructions, R, C, Sr, Sc);        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; i + 1 &lt;&lt; &quot;: &quot; &lt;&lt; ans.first &lt;&lt; &quot; &quot; &lt;&lt; ans.second &lt;&lt; endl;    &#125;    return 0;&#125;

We need a fast way to skip cells that have already been visited. One approach is the interval-recording method from the editorial. Time complexity: O(N log N). Each interval query costs O(log N).
#include &lt;iostream&gt;#include &lt;set&gt;#include &lt;string&gt;#include &lt;vector&gt;#include &lt;cassert&gt;using namespace std;int getNext(set&lt;pair&lt;int, int&gt;&gt; &amp;visited, const int x, int direction) &#123;  auto it = visited.lower_bound(&#123;x + 1, x + 1&#125;);  assert(it != visited.begin());  --it;  if (direction &gt; 0)    return it-&gt;second;  else    return it-&gt;first - 1;&#125;void visitRow(set&lt;pair&lt;int, int&gt;&gt; &amp;row, int y) &#123;  auto it = row.lower_bound(&#123;y + 1, y + 1&#125;);  if (it == row.begin()) &#123;    it = row.insert(&#123;y, y + 1&#125;).first;  &#125; else &#123;    --it;    if (it-&gt;first &lt;= y &amp;&amp; it-&gt;second &gt; y) &#123;      return;    &#125; else if (it-&gt;second == y) &#123;      auto old = it;      it = row.insert(it, &#123;it-&gt;first, it-&gt;second + 1&#125;);      it = row.erase(old);    &#125; else &#123;      it = row.insert(&#123;y, y + 1&#125;).first;    &#125;  &#125;  // merge interval  if (next(it) != row.end() &amp;&amp; next(it)-&gt;first == it-&gt;second) &#123;    int end = next(it)-&gt;second;    int begin = it-&gt;first;    row.erase(next(it));    row.erase(it);    row.insert(&#123;begin, end&#125;);  &#125;&#125;void visit(vector&lt;set&lt;pair&lt;int, int&gt;&gt;&gt; &amp;visitedR,           vector&lt;set&lt;pair&lt;int, int&gt;&gt;&gt; &amp;visitedC, const int x, int y) &#123;  auto &amp;row = visitedR[x];  visitRow(row, y);  auto &amp;column = visitedC[y];  visitRow(column, x);&#125;pair&lt;int, int&gt; solve(const string &amp;instructions, const int R, const int C,                     const int Sr, const int Sc) &#123;  int current_x = Sr, current_y = Sc;  vector&lt;set&lt;pair&lt;int, int&gt;&gt;&gt; visitedR(R + 1);  vector&lt;set&lt;pair&lt;int, int&gt;&gt;&gt; visitedC(C + 1);  visit(visitedR, visitedC, current_x, current_y);  for (char c : instructions) &#123;    switch (c) &#123;    case &#x27;N&#x27;:      current_x = getNext(visitedC[current_y], current_x, -1);      break;    case &#x27;E&#x27;:      current_y = getNext(visitedR[current_x], current_y, 1);      break;    case &#x27;W&#x27;:      current_y = getNext(visitedR[current_x], current_y, -1);      break;    case &#x27;S&#x27;:      current_x = getNext(visitedC[current_y], current_x, 1);      break;    default:      cerr &lt;&lt; &quot;Bad instruction: &quot; &lt;&lt; c &lt;&lt; endl;      break;    &#125;    visit(visitedR, visitedC, current_x, current_y);  &#125;  return &#123;current_x, current_y&#125;;&#125;int main() &#123;  int T;  cin &gt;&gt; T;  for (int i = 0; i &lt; T; ++i) &#123;    int N, R, C, Sr, Sc;    cin &gt;&gt; N &gt;&gt; R &gt;&gt; C &gt;&gt; Sr &gt;&gt; Sc;    string instructions;    cin &gt;&gt; instructions;    auto ans = solve(instructions, R, C, Sr, Sc);    cout &lt;&lt; &quot;Case #&quot; &lt;&lt; i + 1 &lt;&lt; &quot;: &quot; &lt;&lt; ans.first &lt;&lt; &quot; &quot; &lt;&lt; ans.second &lt;&lt; endl;  &#125;  return 0;&#125;

Another approach is the method from Kuang Shen’s livestream. Use Union-Find, and note that direction matters when doing union. The time complexity is O(N).
#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;map&gt;using namespace std;struct UF &#123;    int F[200010];    int find(int x) &#123;        if (F[x] == -1) return x;        return F[x] = find(F[x]);    &#125;    void init() &#123;        memset(F, -1, sizeof(F));    &#125;    void join(int x, int y) &#123;        int t1 = find(x);        int t2 = find(y);        if (t1 != t2) &#123;            F[t2] = t1;        &#125;    &#125;&#125;;UF N, E, W, S;map&lt;pair&lt;int, int&gt;, int&gt; p2Id;int tot;map&lt;int, pair&lt;int, int&gt;&gt; id2P;void init() &#123;    N.init();    E.init();    W.init();    S.init();    tot = 0;    p2Id.clear();    id2P.clear();&#125;int getId(int x, int y) &#123;    pair&lt;int, int&gt; p = make_pair(x, y);    if (!p2Id.count(p)) &#123;        p2Id[p] = tot;        id2P[tot] = p;        tot++;    &#125;    return p2Id[p];&#125;void gao(int x, int y) &#123;    int now = getId(x, y);    int w = getId(x, y-1);    int e = getId(x, y+1);    int n = getId(x-1, y);    int s = getId(x+1, y);    W.join(w, now);    E.join(e, now);    N.join(n, now);    S.join(s, now);&#125;pair&lt;int, int&gt; getNext(int x, int y, char dir) &#123;    int now = getId(x, y);    int nextId;    if (dir == &#x27;N&#x27;) &#123;        nextId = N.find(now);    &#125; else if (dir == &#x27;E&#x27;) &#123;        nextId = E.find(now);    &#125; else if (dir == &#x27;W&#x27;) &#123;        nextId = W.find(now);    &#125; else if (dir == &#x27;S&#x27;) &#123;        nextId = S.find(now);    &#125;    return id2P[nextId];&#125;char str[50010];int main() &#123;    int T;    int iCase = 0;    scanf(&quot;%d&quot;, &amp;T);    while (T--) &#123;        iCase++;        int N, R, C, sx, sy;        scanf(&quot;%d%d%d%d%d&quot;, &amp;N, &amp;R, &amp;C, &amp;sx, &amp;sy);        scanf(&quot;%s&quot;, str);        init();        gao(sx, sy);        pair&lt;int, int&gt; now = make_pair(sx, sy);        for (int i = 0; i &lt; N; ++i) &#123;            now = getNext(now.first, now.second, str[i]);            gao(now.first, now.second);        &#125;        printf(&quot;Case #%d: %d %d\n&quot;, iCase, now.first, now.second);    &#125;    return 0;&#125;

Circuit BoardKuang Shen used a relatively brute-force solution: O(R * C^2).Record, for each cell, the number of cells before it whose difference is within K.Then enumerate each column and K, scan the rows, and update the maximum area.
Judging from the data scale and actual tests, this can pass. Kick Start’s time complexity scale is basically around 10^6.
#include &lt;algorithm&gt;#include &lt;cstdio&gt;using namespace std;int a[310][310];int diff[310][310][310];int main() &#123;  int T;  int iCase = 0;  scanf(&quot;%d&quot;, &amp;T);  while (T--) &#123;    iCase++;    int R, C, K;    scanf(&quot;%d%d%d&quot;, &amp;R, &amp;C, &amp;K);    for (int i = 0; i &lt; R; i++) &#123;      for (int j = 0; j &lt; C; j++) &#123;        scanf(&quot;%d&quot;, &amp;a[i][j]);      &#125;    &#125;    for (int i = 0; i &lt; R; i++) &#123;      for (int j = 0; j &lt; C; ++j) &#123;        int Min = a[i][j];        int Max = a[i][j];        for (int k = j; k &lt; C; ++k) &#123;          Min = min(a[i][k], Min);          Max = max(a[i][k], Max);          diff[i][j][k] = Max - Min;        &#125;      &#125;    &#125;    int ans = 0;    for (int j = 0; j &lt; C; ++j) &#123;        for (int k = j; k &lt; C; ++k) &#123;            int now = 0;            for (int i = 0; i &lt; R; ++i) &#123;                if (diff[i][j][k] &lt;= K) &#123;                    ans = max(ans, (k - j + 1) * (i - now + 1));                &#125; else &#123;                    now = i + 1;                &#125;            &#125;        &#125;    &#125;    printf(&quot;Case #%d: %d\n&quot;, iCase, ans);  &#125;  return 0;&#125;

The official solution is O(N log N).It uses a segment tree to query the maximum and minimum quickly, binary search to determine the right boundary that satisfies K, and largest-rectangle-under-histogram to get the maximum rectangle area.It strongly tests familiarity with advanced data structures and algorithms, as well as the ability to implement them quickly.
#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;algorithm&gt;#include &lt;stack&gt;#include &lt;cmath&gt;using namespace std;// https://www.geeksforgeeks.org/min-max-range-queries-array/// https://www.geeksforgeeks.org/largest-rectangle-under-histogram/struct SegmentTree &#123;    vector&lt;pair&lt;int, int&gt;&gt; st;    int n = 0;    SegmentTree(const vector&lt;int&gt;&amp; a) &#123;        n = a.size();        int x = ceil(log2(n));        int max_size = std::pow(2, x + 1) - 1;        st.resize(max_size);        constructSTUtil(a, 0, n-1, 0);    &#125;    // A recursive function that constructs Segment Tree for array[ss..se].    // si is index of current node in segment tree st    void constructSTUtil(const vector&lt;int&gt;&amp; arr, int ss, int se, int si) &#123;        // If there is one element in array, store it in current node of segment tree and return        if (ss == se) &#123;            st[si].first = arr[ss];            st[si].second = arr[ss];            return;        &#125;        // If there are more than one elements, then recurse for left and right        // subtrees and store the minimum and maximum of two values in this nodee        int mid = ss + (se - ss) / 2;        constructSTUtil(arr, ss, mid, si*2+1);        constructSTUtil(arr, mid+1, se, si*2+2);        st[si].first = min(st[si*2+1].first, st[si*2+2].first);        st[si].second = max(st[si*2+1].second, st[si*2+2].second);    &#125;    /**     * A recursive function to get the minimun and maximum value in a     * given range of array indexes. The following are parameters for thie function.     *      * st --&gt; segment tree vector     * index --&gt; index of current node in the segment tree. Initially 0 is passed as root is always at index 0     * ss &amp;&amp; se --&gt; Starting and ending indexes of the segment represented by current node, i.e. st[index]     * qs &amp;&amp; qe --&gt; Starting and ending indexes of query range     */    pair&lt;int, int&gt; maxMinUtil(int ss, int se, int qs, int qe, int index) &#123;        // if segment of this node is a part of given range,        // then return the minimum and maximum node of the segment        if (ss &gt;= qs &amp;&amp; se &lt;= qe) &#123;            return st[index];        &#125;        // If segment of this node is outside the given range        if (se &lt; qs || ss &gt; qe) &#123;            return &#123;numeric_limits&lt;int&gt;::max(), numeric_limits&lt;int&gt;::min()&#125;;        &#125;        // If a part of this segment overlaps with the given range        int mid = ss + (se - ss) / 2;        auto left = maxMinUtil(ss, mid, qs, qe, index*2+1);        auto right = maxMinUtil(mid+1, se, qs, qe, index*2+2);        return &#123;min(left.first, right.first), max(left.second, right.second)&#125;;    &#125;    pair&lt;int, int&gt; maxMin(int qs, int qe) &#123;        if (qs &lt; 0 || qe &gt; n - 1 || qs &gt; qe) &#123;            cerr &lt;&lt; &quot;Invalid Input&quot; &lt;&lt; endl;            return &#123;numeric_limits&lt;int&gt;::max(), numeric_limits&lt;int&gt;::min()&#125;;        &#125;        return maxMinUtil(0, n-1, qs, qe, 0);    &#125;    int queryDiff(int qs, int qe) &#123;        auto ans = maxMin(qs, qe);        return ans.second - ans.first;    &#125;&#125;;int solve(const vector&lt;vector&lt;int&gt;&gt;&amp; board, int K) &#123;    int R = board.size();    int C = board[0].size();    vector&lt;vector&lt;int&gt;&gt; heigth(R, vector&lt;int&gt;(C));    for (int i = 0; i &lt; R; ++i) &#123;        auto maxMin = SegmentTree(board[i]);        for (int j = 0; j &lt; C; ++ j) &#123;            int lo = j, hi = C;            while (lo &lt; hi) &#123;                int mid = lo + (hi - lo) / 2;                if (maxMin.queryDiff(j, mid) &lt;= K) &#123;                    lo = mid + 1;                &#125; else &#123;                    hi = mid;                &#125;            &#125;            heigth[i][j] = lo - j;        &#125;    &#125;    int ans = 0;    for (int j = 0; j &lt; C; ++j) &#123;        stack&lt;int&gt; s;        int i = 0;        while (i &lt; R) &#123;            if (s.empty() || heigth[s.top()][j] &lt;= heigth[i][j]) &#123;                s.push(i);                ++i;            &#125; else &#123;                int tp = s.top();                s.pop();                ans = max(ans, heigth[tp][j] * (s.empty() ? i : i - s.top() - 1));            &#125;        &#125;        while (!s.empty()) &#123;            int tp = s.top();            s.pop();            ans = max(ans, heigth[tp][j] * (s.empty() ? i : i - s.top() - 1));        &#125;    &#125;    return ans;&#125; int main() &#123;  int T;  cin &gt;&gt; T;  for (int i = 1; i &lt;= T; ++i) &#123;      int R, C, K;      cin &gt;&gt; R &gt;&gt; C &gt;&gt; K;      vector&lt;vector&lt;int&gt;&gt; board(R, vector&lt;int&gt;(C));      for (int j = 0; j &lt; R; ++j) &#123;          for (int k = 0; k &lt; C; ++k) &#123;              cin &gt;&gt; board[j][k];          &#125;      &#125;      int ans = solve(board, K);      cout &lt;&lt; &quot;Case #&quot; &lt;&lt; i &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;  &#125;  return 0;&#125;


Catch SomeA classic DP problem.Each shirt color definitely only needs to be worn once, because two trips are definitely longer than one trip, while the number of observed dogs is the same.Each color has two minimum costs: one where we need to return to the origin, and one where we do not.dp[i][j][0/1] represents the minimum cost after using the first i colors and observing j dogs, without returning / returning to the origin.
#include &lt;algorithm&gt;#include &lt;vector&gt;#include &lt;cstdio&gt;using namespace std;int P[1010], A[1010];int dp[1010][1010][2];const int INF = 0x3f3f3f3f;vector&lt;int&gt; vec[1010];int main() &#123;    int T;    int iCase = 0;    scanf(&quot;%d&quot;, &amp;T);    while (T--) &#123;        iCase++;        int n, k;        scanf(&quot;%d%d&quot;, &amp;n, &amp;k);        for (int i = 0; i &lt; n; ++i) &#123;            scanf(&quot;%d&quot;, &amp;P[i]);        &#125;        for (int i = 0; i &lt; n; ++i) &#123;            scanf(&quot;%d&quot;, &amp;A[i]);        &#125;        for (int i = 1; i &lt;= 1000; ++i) &#123;            vec[i].clear();        &#125;        for (int i = 0; i &lt; n; ++i) &#123;            vec[A[i]].push_back(P[i]);        &#125;        for (int i = 1; i &lt;= 1000; ++i) &#123;            sort(vec[i].begin(), vec[i].end());        &#125;         for (int i = 0; i &lt;= 1000; ++i) &#123;            for (int j = 0; j &lt;= n; ++j) &#123;                dp[i][j][0] = dp[i][j][1] = INF;            &#125;        &#125;        dp[0][0][0] = dp[0][0][1] = 0;        for (int i = 0; i &lt; 1000; ++i) &#123;            for (int j = 0; j &lt;= n;++j) &#123;                if (dp[i][j][0] == INF &amp;&amp; dp[i][j][1] == INF) &#123;                    continue;                &#125;                int sz = vec[i+1].size();                for (int x = 0; x &lt;= sz; ++x) &#123;                    int tmp = x == 0 ? 0 : vec[i+1][x-1];                    dp[i+1][j+x][0] = min(dp[i+1][j+x][0], dp[i][j][0] + 2 * tmp);                    dp[i+1][j+x][1] = min(dp[i+1][j+x][1], dp[i][j][0] + tmp);                    dp[i+1][j+x][1] = min(dp[i+1][j+x][1], dp[i][j][1] + 2 * tmp);                &#125;            &#125;        &#125;        printf(&quot;Case #%d: %d\n&quot;, iCase, dp[1000][k][1]);    &#125;&#125;

