Code-Eat SwitcherTest set 1:S = 1 or 2. We can solve it by writing inequalities.When S = 2, there are two variables, and the process of solving inequalities is similar to linear programming.
During the contest, my idea was correct, but because I wrote the wrong return value when S = 1, I could not get AC for a long time. At that time I kept debugging the logic for S = 2 and completely failed to think that S = 1 could be wrong.
#include &lt;vector&gt;#include &lt;iostream&gt;#include &lt;unordered_map&gt;#include &lt;map&gt;#include &lt;cmath&gt;using namespace std;bool solve(const vector&lt;pair&lt;int, int&gt;&gt;&amp; energy, const int S, double code, double eat) &#123;    if (S == 1) &#123;        double Ci = energy[0].first;        double Ei = energy[0].second;        return code / Ci + eat / Ei &lt;= 1;    &#125; else if (S == 2) &#123;        double C1 = energy[0].first, C2 = energy[1].first;        double E1 = energy[0].second, E2 = energy[1].second;        if (C1 / C2 == E1 / E2) &#123;            vector&lt;pair&lt;int, int&gt;&gt; tmp = &#123;make_pair(energy[0].first + energy[1].first, energy[0].second + energy[1].second)&#125;;            return solve(tmp, 1, code, eat);        &#125;        double C = code, E = eat;        double x = (C / C2 - 1 + E / E2 - E1 / E2) / (C1 / C2 - E1 / E2);        double y = C / C2 - x * C1 / C2;        // cout &lt;&lt; &quot;result: &quot; &lt;&lt; x &lt;&lt; &quot;, &quot; &lt;&lt; y &lt;&lt; &quot;|&quot; &lt;&lt; x * C1 + y * C2 &lt;&lt; &quot;, &quot; &lt;&lt; (1 - x) * E1 + (1 - y) * E2 &lt;&lt; &quot; | &quot; &lt;&lt;         // 1 - E / E2 + E1 / E2 - x * E1 / E2        // &lt;&lt; endl;        if (x &gt; 1) &#123;            return 1 - E / E2 + E1 / E2 - 1 * E1 / E2 &gt;= C / C2 - 1 * C1 / C2;        &#125;        if (y &gt; 1) &#123;            return (1 - E / E2 + E1 / E2 - 1) * (E2 / E1) &gt;= (C / C2 - 1) * (C2 / C1);        &#125;        if (x &lt; 0) &#123;            return 1 - E / E2 + E1 / E2 &gt;= C / C2;        &#125;        if (y &lt; 0) &#123;            return (1 - E / E2 + E1 / E2) * (E2 / E1) &gt;= (C / C2) * (C2 / C1);        &#125;        return true;        // return x &gt;= 0 &amp;&amp; y &gt;= 0 &amp;&amp; x &lt;= 1 &amp;&amp; y &lt;= 1;    &#125; else &#123;        return false;    &#125;&#125;int main()&#123;	int T;	cin &gt;&gt; T;	for (int i = 0; i &lt; T; ++i)	&#123;		int D, S;        cin &gt;&gt; D &gt;&gt; S;        string ans;        vector&lt;pair&lt;int, int&gt;&gt; energy(S);        for (int i = 0; i &lt; S; ++i) &#123;            cin &gt;&gt; energy[i].first &gt;&gt; energy[i].second;        &#125;        for (int i = 0; i &lt; D; ++i) &#123;            int A, B;            cin &gt;&gt; A &gt;&gt; B;            bool yes = solve(energy, S, A, B);            if (yes) &#123;                ans.push_back(&#x27;Y&#x27;);            &#125; else &#123;                ans.push_back(&#x27;N&#x27;);            &#125;        &#125;		cout &lt;&lt; &quot;Case #&quot; &lt;&lt; i + 1 &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;	&#125;	return 0;&#125;

Test Set 2Observation: for each slot, for every one unit of eating energy obtained, we lose $C_i / E_i$ units of coding energy. So if $C_i / E_i &lt; C_j / E_j$, the better choice is always i.Based on this observation, we sort the slots by $C_i / E_i$, compute the prefix sum of E and the suffix sum of C. For each day, use binary search to find the boundary point that satisfies eating, then judge whether coding can also be satisfied.
#include &lt;cmath&gt;#include &lt;iostream&gt;#include &lt;map&gt;#include &lt;unordered_map&gt;#include &lt;vector&gt;#include &lt;algorithm&gt;using namespace std;bool solve(const vector&lt;pair&lt;int, int&gt;&gt; &amp;energy, const int S,           const vector&lt;int&gt; &amp;prefix, const vector&lt;int&gt; &amp;suffix, int code,           int eat) &#123;    auto it = lower_bound(prefix.begin(), prefix.end(), eat);    int index = distance(prefix.begin(), it);    if (index == S) &#123;        return false;    &#125;    double need;    if (index == 0) &#123;        need = eat;    &#125; else &#123;        need = eat - prefix[index - 1];    &#125;    double f = need / energy[index].second;    double code_have;    if (index == S - 1) &#123;        code_have = 0;    &#125; else &#123;        code_have = suffix[index + 1];    &#125;    double code_need = code - code_have;    return (1 - f) * energy[index].first &gt;= code_need;&#125;int main() &#123;    int T;    cin &gt;&gt; T;    for (int i = 0; i &lt; T; ++i) &#123;        int D, S;        cin &gt;&gt; D &gt;&gt; S;        string ans;        vector&lt;pair&lt;int, int&gt;&gt; energy(S);        for (int i = 0; i &lt; S; ++i) &#123;            cin &gt;&gt; energy[i].first &gt;&gt; energy[i].second;        &#125;        sort(energy.begin(), energy.end(),             [](const auto &amp;lhs, const auto &amp;rhs) -&gt; bool &#123;                 return lhs.first / static_cast&lt;double&gt;(lhs.second) &lt;                        rhs.first / static_cast&lt;double&gt;(rhs.second);             &#125;);        // build prefix cumulative for eating        vector&lt;int&gt; prefix(S);        int current = 0;        for (int i = 0; i &lt; S; ++i) &#123;            current += energy[i].second;            prefix[i] = current;        &#125;        // build suffix cumulative for coding        vector&lt;int&gt; suffix(S);        current = 0;        for (int i = S - 1; i &gt;= 0; --i) &#123;            current += energy[i].first;            suffix[i] = current;        &#125;        // binary search for each day        for (int i = 0; i &lt; D; ++i) &#123;            int A, B;            cin &gt;&gt; A &gt;&gt; B;            bool yes = solve(energy, S, prefix, suffix, A, B);            if (yes) &#123;                ans.push_back(&#x27;Y&#x27;);            &#125; else &#123;                ans.push_back(&#x27;N&#x27;);            &#125;        &#125;        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; i + 1 &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;    &#125;    return 0;&#125;

Street CheckersWhether a number X is interesting can be transformed into |(# of odd divisors) - (# of even divisors)| &lt;= 2.For the dataset where R &lt; 10^6, we can preprocess all numbers less than 10^6 to obtain the number of divisors for each, with time complexity O(sqrt(X)), then build the prefix sum of interesting numbers in [1, X]. For a query [L, R], we can then get the answer in O(1). The total time complexity is $O(R_{max} \sqrt{R_{max}} + T)$: preprocessing plus T test cases.
For the large dataset, we need to continue observing.Every divisor of an odd number is still odd. Every integer X can be written as $X = A \times 2 ^ p$, where A is an odd number, and X is a non-negative integer.Therefore, we can divide all divisors of X into groups, where $d_1$,$d_2$,…,$d_k$ are the divisors of A.
${d_1, d_1 * 2, d_1 * 2^2, \dots, d_1 * 2^p}$${d_2, d_2 * 2, d_2 * 2^2, \dots, d_2 * 2^p}$$\dots$${d_k, d_k * 2, d_k * 2^2, \dots, d_k * 2^p}$
We can see that the number of odd divisors is k, (k &gt;= 1, at least the odd divisor 1 exists).The number of even divisors is k * X.The odd-even difference is $|k(X-1)| \le 2$.The solutions are:

Case 1: X = 0, k = 1 or 2

Case 2: X = 1, k can be any value

Case 3: X = 2, k = 1 or 2

Case 4: X = 3, k = 1

Case 1 means 1 or an odd prime.

Case 2 means A can be any odd number, so the original number has the form $ 2*(2n + 1) = 4 * n + 2$, which can be counted in O(1).

Case 3 means A is 1 or any odd prime. That is, the number of odd primes in [L / 4, R / 4].

Case 4 only represents the number 8.The number of primes can be computed using the Sieve of Eratosthenes.


Time complexity: $O(T * (R - L + 1) * log(\sqrt{R}))$

This round was the second-to-last round of the year, and also a relatively easy one.
I solved the third problem and the small data sets for problems 1 and 2. My algorithm for the second problem was correct in itself, but I did not correctly estimate the maximum number of bits in k or prevent overflow, so I got WA on the large data set. The first problem was not hard either, but I was not sensitive enough to divisors, so I missed the better solution. Overall, this was the closest I got to AC in a round. My luck was relatively good, and I finished the contest one hour early. Later, because I really could not think of more solutions or details to watch out for, I gave up.
Book ReadingBrute force plus memoization can pass directly. But I wrote the memoization wrong and forgot to actually memoize. That caused TLE and lost quite a few points. What a pity.
Also, if you can use long long, do not use int; otherwise the final ans will overflow.
Time complexity: O(N log N).
Because memoization exists, the number of pages calculated is at most 1 + 1 / 2 + 1 / 3 + ... + 1 / N = log N, the harmonic series.
#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;unordered_map&gt;using namespace std;using ll = long long;int main() &#123;    ll T;    cin &gt;&gt; T;    for (ll iCase = 1; iCase &lt;= T; ++iCase) &#123;        ll ans = 0;        ll N, M, Q;        cin &gt;&gt; N &gt;&gt; M &gt;&gt; Q;        vector&lt;bool&gt; pages(N + 1, true);        pages[0] = false;        for (ll i = 0; i &lt; M; ++i) &#123;            ll P;            cin &gt;&gt; P;            pages[P] = false;        &#125;        unordered_map&lt;ll, ll&gt; memo;        for (ll i = 0; i &lt; Q; ++i) &#123;            ll R;            cin &gt;&gt; R;            ll count = 0;            if (memo.find(R) != memo.end()) &#123;                count = memo[R];            &#125; else &#123;                for (ll j = 1; j * R &lt;= N; ++j) &#123;                    if (pages[j * R]) &#123;                        ++count;                    &#125;                &#125;                memo[R] = count;            &#125;            ans += count;        &#125;        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;    &#125;&#125;

The EquationThere are quite a few details to pay attention to in this problem, though the algorithm itself is not difficult.

The long long constant should be 1L; otherwise 1 defaults to int, which creates overflow risk.
We cannot start searching from the highest bit in A, because k may be a larger number. Instead, we should consider the maximum value of k from the perspective of M. Here M has 15 decimal digits, corresponding to around 50 binary bits. However, we also cannot start from too high a bit, otherwise N * (1 &lt;&lt; i) will overflow 64 bits. Since the maximum N is 1000, around 10 binary bits, we can start searching from bits 50 to 53.

Since we want to maximize k, we can use a greedy idea: from high bits to low bits, try to place 1 whenever possible; otherwise place 0 and backtrack when the requirement is exceeded.
Because there is a lot of backtracking and pruning, the time complexity is not easy to analyze. But it can pass the large data set.
#include &lt;iostream&gt;#include &lt;vector&gt;using namespace std;using ll = long long;ll backtracking(const vector&lt;ll&gt; &amp;bits, const ll N, const ll M, ll position,                ll accu, ll k) &#123;    ll one = bits[position];    ll zero = N - one;    // k always wants to be 1 in position i    ll i = position;    if (position &lt; 0) &#123;        return k;    &#125;    ll ret = -1;    if (accu + zero * (1L &lt;&lt; i) &lt;= M) &#123; // if one        ret = backtracking(bits, N, M, position - 1,                           accu + zero * (1L &lt;&lt; i),                           k + (1L &lt;&lt; i));    &#125;    if (ret == -1) &#123; // zero        if (accu + one * (1L &lt;&lt; i) &lt;= M) &#123;            ret = backtracking(bits, N, M, position - 1,                               accu + one * (1L &lt;&lt; i), k);        &#125;    &#125;    return ret;&#125;int main() &#123;    ll T;    cin &gt;&gt; T;    for (ll iCase = 1; iCase &lt;= T; ++iCase) &#123;        ll ans = 0;        ll N, M;        cin &gt;&gt; N &gt;&gt; M;        vector&lt;ll&gt; bits(64, 0);        ll max_position = 0;        for (ll i = 0; i &lt; N; ++i) &#123;            ll A;            cin &gt;&gt; A;            ll position = 0;            while (A &gt; 0) &#123;                ll last_bit = A % 2;                if (last_bit &gt; 0) &#123;                    ++bits[position];                    max_position = max(max_position, position);                &#125;                A = A / 2;                ++position;            &#125;        &#125;        ans = backtracking(bits, N, M, 53, 0, 0);        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;    &#125;&#125;

ShiftsSame as the second problem, I used backtracking with a lot of pruning and memoization to enumerate all combinations. I did not expect it to pass.
The official solution uses divide and conquer: enumerate the combinations of two smaller sets separately, then iterate over all combinations and find the number of combinations that satisfy the requirements after merging. This is the meet-in-the-middle approach.
#include &lt;cmath&gt;#include &lt;iostream&gt;#include &lt;map&gt;#include &lt;vector&gt;using namespace std;using ll = long long;ll backtracking(const vector&lt;ll&gt; &amp;A, const vector&lt;ll&gt; &amp;B,                const vector&lt;ll&gt; &amp;suffixA, const vector&lt;ll&gt; &amp;suffixB, ll needA,                ll needB, ll position, map&lt;tuple&lt;ll, ll, ll&gt;, ll&gt; &amp;memo,                map&lt;tuple&lt;ll, ll&gt;, ll&gt; &amp;memoA, map&lt;tuple&lt;ll, ll&gt;, ll&gt; &amp;memoB) &#123;    const ll n = A.size();    if (position &gt;= n) &#123;        return needA &lt;= 0 &amp;&amp; needB &lt;= 0 ? 1 : 0;    &#125;    auto it = memo.find(&#123;needA, needB, position&#125;);    if (it != memo.end()) &#123;        return it-&gt;second;    &#125;    if (needA &lt;= 0 &amp;&amp; needB &lt;= 0) &#123;        return memo[&#123;needA, needB, position&#125;] = pow(3, n - position);    &#125;    if (needA &gt; suffixA[position] || needB &gt; suffixB[position]) &#123;        return memo[&#123;needA, needB, position&#125;] = 0;    &#125;    if (needA &lt;= 0) &#123;        auto it = memoA.find(&#123;needB, position&#125;);        if (it != memoA.end()) &#123;            return it-&gt;second;        &#125;    &#125;    if (needA &lt;= 0) &#123;        auto it = memoA.find(&#123;needB, position&#125;);        if (it != memoA.end()) &#123;            return it-&gt;second;        &#125;    &#125;    if (needB &lt;= 0) &#123;        auto it = memoB.find(&#123;needA, position&#125;);        if (it != memoB.end()) &#123;            return it-&gt;second;        &#125;    &#125;    ll ret = 0;    ret += backtracking(A, B, suffixA, suffixB, needA - A[position],                        needB - B[position], position + 1, memo, memoA, memoB);    ret += backtracking(A, B, suffixA, suffixB, needA, needB - B[position],                        position + 1, memo, memoA, memoB);    ret += backtracking(A, B, suffixA, suffixB, needA - A[position], needB,                        position + 1, memo, memoA, memoB);    if (needA &lt;= 0) &#123;        memoA[&#123;needB, position&#125;] = ret;    &#125;    if (needB &lt;= 0) &#123;        memoB[&#123;needA, position&#125;] = ret;    &#125;    return memo[&#123;needA, needB, position&#125;] = ret;&#125;int main() &#123;    ll T;    cin &gt;&gt; T;    for (ll iCase = 1; iCase &lt;= T; ++iCase) &#123;        ll N, H;        cin &gt;&gt; N &gt;&gt; H;        vector&lt;ll&gt; A(N), B(N), suffixA(N), suffixB(N);        for (int i = 0; i &lt; N; ++i) &#123;            cin &gt;&gt; A[i];        &#125;        for (int i = 0; i &lt; N; ++i) &#123;            cin &gt;&gt; B[i];        &#125;        if (N &gt; 0) &#123;            suffixA[N - 1] = A[N - 1];            suffixB[N - 1] = B[N - 1];        &#125;        for (int i = N - 2; i &gt;= 0; --i) &#123;            suffixA[i] = A[i] + suffixA[i + 1];            suffixB[i] = B[i] + suffixB[i + 1];        &#125;        map&lt;tuple&lt;ll, ll, ll&gt;, ll&gt; memo;        map&lt;tuple&lt;ll, ll&gt;, ll&gt; memoA;        map&lt;tuple&lt;ll, ll&gt;, ll&gt; memoB;        auto ans =            backtracking(A, B, suffixA, suffixB, H, H, 0, memo, memoA, memoB);        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;    &#125;&#125;

Kick Start has changed a little in the new year:

Whether all test results are correct is now returned immediately. Previously, large dataset results could only be seen after the contest. This is effectively a difficulty reduction and reduces the cost of mistakes for contestants. In the past, one small mistake meant losing the score for the large dataset. Now it is more like adding a time penalty.
The number of problems changed from 3 to 4, with the time unchanged, adding one easier problem for points.

Rank 570. Because everyone got 100 points, the final comparison was all about time. Since the contest was from 12:00 to 15:00, I spent half an hour in the middle eating lunch. Also, none of the problems were accepted on the first try; I debugged all of them with printf, which took quite a bit of time. The fastest experts finished in 20 minutes.
