Round A problem link
AllocationAt first I thought it was a simple knapsack problem, but later realized it was an even simpler greedy problem. Because the goal is to maximize the number of houses bought, rather than maximize value, or in other words every house has value 1. So greedy is enough. In short, it is an easy warm-up problem.Sort the houses by price from small to large, and buy the cheap ones first.
Time complexity: O(N log N),space complexity: O(N).
#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;algorithm&gt;using namespace std;vector&lt;int&gt; A(100005);int main() &#123;    int T;    cin &gt;&gt; T;    for (int iCase = 1; iCase &lt;= T; ++iCase) &#123;        int N, B;        cin &gt;&gt; N &gt;&gt; B;        for (int i = 0; i &lt; N; ++i) &#123;            cin &gt;&gt; A[i];        &#125;        sort(A.begin(), A.begin() + N);        int ans = 0;        int index = 0;        while (index &lt; N &amp;&amp; B &gt;= A[index]) &#123;            B -= A[index];            ++ans;            ++index;        &#125;        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt;endl;    &#125;    return 0;&#125;
Because I forgot to check index &lt; n during the greedy process, I got one WA penalty.
PlatesDynamic Programming.State transition:For the i-th stack, after taking j plates, the maximum Beauty value obtained.dp[i][j] = max&#123;dp[i-1][x] + top_sum[j - x] for x in [0, j]&#125;.
Time complexity: O(N * P * P) 50 * 1500 * 1500,space complexity: O(N * P) 50 * 1500 -&gt; O(P) 1500.
#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;algorithm&gt;using namespace std;vector&lt;int&gt; dp(1505, 0);vector&lt;int&gt; line(35);int main() &#123;    int T;    cin &gt;&gt; T;    for (int iCase = 1; iCase &lt;= T; ++iCase) &#123;        int N, K, P;        cin &gt;&gt; N &gt;&gt; K &gt;&gt; P;        fill(dp.begin(), dp.end(), 0);        for (int i = 0; i &lt; N; ++i) &#123;            for (int j = 0; j &lt; K; ++j) &#123;                cin &gt;&gt; line[j];                if (j &gt; 0)                    line[j] += line[j - 1];            &#125;            for (int j = P; j &gt; 0; --j) &#123;                int max_dp = dp[j];                for (int x = j - 1; x &gt;= 0 &amp;&amp; j - x - 1 &lt; K; --x) &#123;                    max_dp = max(max_dp, dp[x] + line[j - x - 1]);                &#125;                dp[j] = max_dp;                // cout &lt;&lt; dp[j] &lt;&lt; &quot;, &quot;;            &#125;            // cout &lt;&lt; endl;        &#125;        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; dp[P] &lt;&lt;endl;    &#125;    return 0;&#125;

WorkoutFor the case K == 1, we can directly use a greedy strategy and split the largest interval evenly.
For the case K &gt; 1, we can solve it by converting the optimization problem into a decision problem.The optimization problem is: find the minimum difficulty.The decision problem is: can difficulty == x be achieved? The time complexity is O(N * K).Then the distribution of answers to the decision problem is: ... F F F T T T ..., and we need to find the first T.Use binary search, with search interval [1, max(M_i) = 1^9], and time complexity O(log 1e9).So overall:time complexity: O(N * K * log 1e9),space complexity: O(N).
#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;algorithm&gt;using namespace std;vector&lt;int&gt; M(1e5 + 5);int main() &#123;    int T;    cin &gt;&gt; T;    for (int iCase = 1; iCase &lt;= T; ++iCase) &#123;        int N, K;        cin &gt;&gt; N &gt;&gt; K;        for (int i = 0; i &lt; N; ++i) &#123;            cin &gt;&gt; M[i];        &#125;        auto determine = [&amp;](int x) -&gt; bool &#123;            int used = 0;            for (int i = 0; i &lt; N - 1; ++i) &#123;                int difference = M[i + 1] - M[i];                while (difference &gt; x) &#123;                    ++used;                    if (used &gt; K)                        return false;                    difference -= x;                &#125;            &#125;            return true;        &#125;;        int lo = 1, hi = 1e9;        while (lo &lt; hi) &#123;            int mid = lo + (hi - lo) / 2;            auto deter = determine(mid);            // cout &lt;&lt; mid &lt;&lt; &quot;: &quot; &lt;&lt; deter &lt;&lt; endl;            if (deter) &#123;                hi = mid;            &#125; else &#123;                lo = mid + 1;            &#125;        &#125;        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; lo &lt;&lt;endl;    &#125;    return 0;&#125;

BundlingTrie + DFS + Greedy.
Because common prefixes are needed, we can preprocess the strings with a Trie.Use DFS to search the Trie and try to form groups as deep as possible, which gives a larger score.
Time complexity: O(characters.size()), 2 * 10 ^ 6.Space complexity: O(characters.size()).
#include &lt;algorithm&gt;#include &lt;iostream&gt;#include &lt;memory&gt;#include &lt;vector&gt;#include &lt;functional&gt;#include &lt;cassert&gt;using namespace std;struct Trie &#123;    int passby = 0;    int destination = 0;    array&lt;shared_ptr&lt;Trie&gt;, 26&gt; data;&#125;;void build_tire(shared_ptr&lt;Trie&gt; root, const string &amp;s, int index) &#123;    ++root-&gt;passby;    if (index == s.size()) &#123;        ++root-&gt;destination;        return;    &#125;    if (root-&gt;data[s[index] - &#x27;A&#x27;] == nullptr) &#123;        root-&gt;data[s[index] - &#x27;A&#x27;] = make_shared&lt;Trie&gt;();    &#125;    build_tire(root-&gt;data[s[index] - &#x27;A&#x27;], s, index + 1);&#125;int main() &#123;    int T;    cin &gt;&gt; T;    for (int iCase = 1; iCase &lt;= T; ++iCase) &#123;        int N, K;        cin &gt;&gt; N &gt;&gt; K;        auto root = make_shared&lt;Trie&gt;();        for (int i = 0; i &lt; N; ++i) &#123;            string s;            cin &gt;&gt; s;            build_tire(root, s, 0);        &#125;        int ans = 0;        // return left number        function&lt;int(shared_ptr&lt;Trie&gt;, int)&gt; dfs = [&amp;](shared_ptr&lt;Trie&gt; r,                                                       int depth) -&gt; int &#123;            if (r == nullptr)                return 0;            int now = r-&gt;destination;            for (int i = 0; i &lt; 26; ++i) &#123;                now += dfs(r-&gt;data[i], depth + 1);                // cout &lt;&lt;  depth &lt;&lt; &quot;: &quot; &lt;&lt; char(&#x27;A&#x27; + i) &lt;&lt; &quot;: &quot; &lt;&lt; now &lt;&lt; endl;            &#125;            ans += depth * (now / K);            return now % K;        &#125;;        int r = dfs(root, 0);        // cout &lt;&lt; &quot;r: &quot; &lt;&lt; r &lt;&lt; endl;        cout &lt;&lt; &quot;Case #&quot; &lt;&lt; iCase &lt;&lt; &quot;: &quot; &lt;&lt; ans &lt;&lt; endl;    &#125;    return 0;&#125;

