t; void &#123;            cnt[diff[i]].insert(i);            reverseCnt[cnt[diff[i]].size()].insert(diff[i]);            reverseCnt[cnt[diff[i]].size() - 1].erase(diff[i]);            if (reverseCnt[cnt[diff[i]].size() - 1].empty()) &#123;                reverseCnt.erase(cnt[diff[i]].size() - 1);            &#125;        &#125;;        auto eraseCnt = [&amp;](const int i) -&gt; void &#123;            auto&amp; first = cnt[diff[i]];            first.erase(first.find(i));            reverseCnt[cnt[diff[i]].size() + 1].erase(diff[i]);            if (reverseCnt[cnt[diff[i]].size() + 1].empty()) &#123;                reverseCnt.erase(cnt[diff[i]].size() + 1);            &#125;            if (first.empty()) &#123;                cnt.erase(diff[i]);            &#125;            reverseCnt[cnt[diff[i]].size()].insert(diff[i]);        &#125;;        for (int i = 1; i &lt; x; ++i) &#123;            addCnt(i);        &#125;        auto check = [&amp;](const int lastIdx) -&gt; bool &#123;            // cout &lt;&lt; lastIdx &lt;&lt; &quot; ... &quot; &lt;&lt; cnt &lt;&lt; &quot; &quot; &lt;&lt; maxDiffIndex &lt;&lt; &quot; &quot; &lt;&lt; maxDiffValue &lt;&lt; endl;            auto it = reverseCnt.begin();            const int maxDiffValue = it-&gt;first;            const int maxDiffIndex = *(it-&gt;second.begin());            if (maxDiffValue == x - 1) return true;            else if (maxDiffValue == x - 2 || maxDiffValue == x - 3) &#123;                vector&lt;int&gt; index;                index.reserve(2);                for (const auto&amp; p : cnt) &#123;                    if (p.first != maxDiffIndex) &#123;                        for (const auto&amp; idx : p.second) &#123;                            index.push_back(idx);                        &#125;                    &#125;                &#125;                if (maxDiffValue == x - 2) &#123;                    if (index[0] == lastIdx || index[0] == lastIdx - x + 2) return true;                    else return false;